<script>const responses={Grounded:['You have a steady starting point.','Keep the rhythm: one minute of breathing, then carry on.'],Tired:['Your energy is a signal, not a failure.','Try the 60-second reset and choose one thing to make easier.'],Stretched:['You do not have to hold everything at once.','Pause, name the pressure, and take the smallest useful next step.'],Hopeful:['There is something worth building on here.','Capture one sentence about what feels possible today.']};const result=document.getElementById('checkinResult'),toast=document.getElementById('toast');document.querySelectorAll('[data-mood]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.mood').forEach(item=>item.classList.remove('selected'));button.classList.add('selected');const [headline,next]=responses[button.dataset.mood];result.innerHTML='<strong>'+headline+'</strong>'+next;toast.textContent='Check-in captured for the demo';toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1800)}));</script>
